/**
 * The migrate process: applies the migration history (drizzle/, generated by drizzle-kit and reviewed, plus hand-written
 * SQL for triggers, grants and policies) as the owner role, itrms_owner. The Compose `migrate` service runs it before the
 * API starts; it exits 0 when the database is current.
 */
import { join } from 'node:path';

import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { Pool } from 'pg';

import { fail, start } from './start';

/** Next to the bundle: dist/../drizzle (the image ships both). */
const MIGRATIONS = join(__dirname, '..', 'drizzle');

async function main() {
    const { config, logger } = start('migrate');
    const pool = new Pool({ connectionString: config.DATABASE_MIGRATE_URL, application_name: 'itrms-migrate' });
    try {
        await migrate(drizzle(pool), {
            migrationsFolder: MIGRATIONS,
            migrationsSchema: 'drizzle',
            migrationsTable: '__drizzle_migrations'
        });
        logger.info('migrations applied');
    } catch (error) {
        fail(logger, error);
    } finally {
        await pool.end();
    }
}

void main();
